  @protected
  void sse_encode_frb_download_bytes_event(
    FrbDownloadBytesEvent self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case FrbDownloadBytesEvent_Progress(
        received: final received,
        total: final total,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_32(received, serializer);
        sse_encode_u_32(total, serializer);
      case FrbDownloadBytesEvent_Done(bytes: final bytes):
        sse_encode_i_32(1, serializer);
        sse_encode_list_prim_u_8_strict(bytes, serializer);
    }
  }

